const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Puerto Rico geometry
  const puertoRico = ee.Geometry.Rectangle([-67.3, 17.9, -65.2, 18.5]);

  // Define dates
  const date1 = '2016-09-21';
  const date2 = '2016-09-22';

  console.log("Analyzing nighttime lights for Puerto Rico...");

  // Try VNP46A2 - VIIRS Daily Gridded Day Night Band
  let col1 = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
    .filterBounds(puertoRico)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'));

  let col2 = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
    .filterBounds(puertoRico)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'));

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Sept 21 images: ${size1}`);
  console.log(`Sept 22 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("No daily VIIRS data found. Trying monthly composite...");

    // Fallback to monthly data - get September 2016
    const monthly = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
      .filterBounds(puertoRico)
      .filterDate('2016-09-01', '2016-09-30');

    const monthlySize = await monthly.size().getInfo();
    console.log(`Monthly images: ${monthlySize}`);

    if (monthlySize === 0) {
      console.log("No data available for September 2016.");
      console.log("<answer>C1</answer>");
      return;
    }

    console.log("Cannot assess daily change with monthly data.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get images
  const img1 = ee.Image(col1.first());
  const img2 = ee.Image(col2.first());

  // Use DNB_BRDF-Corrected_NTL band (BRDF-corrected nighttime lights)
  const band = 'DNB_BRDF-Corrected_NTL';

  // Calculate mean nighttime light intensity with pixel count
  const stats1 = await img1.select(band).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: puertoRico,
    scale: 5000,
    maxPixels: 1e9,
    bestEffort: true
  }).getInfo();

  const stats2 = await img2.select(band).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: puertoRico,
    scale: 5000,
    maxPixels: 1e9,
    bestEffort: true
  }).getInfo();

  const mean1 = stats1[band + '_mean'];
  const count1 = stats1[band + '_count'];
  const mean2 = stats2[band + '_mean'];
  const count2 = stats2[band + '_count'];

  console.log(`Sept 21: Mean=${mean1}, Pixels=${count1}`);
  console.log(`Sept 22: Mean=${mean2}, Pixels=${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 == null || mean2 == null || isNaN(mean1) || isNaN(mean2)) {
    console.log("Calculation returned invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  const decline = mean2 < mean1;
  const percentChange = ((mean2 - mean1) / mean1 * 100).toFixed(2);

  console.log(`Change: ${percentChange}% (${decline ? 'Decline' : 'Increase/Stable'})`);

  if (decline) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
